import type { StatBlock } from "../types";

export interface ConfirmedMon {
  no: number;
  name: string;
  types: string[];
  base: StatBlock;
  abilities: string[];
  total: number;
  typeVerified: boolean; // false=チャンピオンズ新規メガ等でタイプ未公表（素の型を仮採用・要確認）
}

const B = (h: number, a: number, b: number, c: number, d: number, s: number): StatBlock =>
  ({ H: h, A: a, B: b, C: c, D: d, S: s });

